<?php $states=['pending'=>'Noch nicht verarbeitet','ready'=>'Verarbeitet','partial'=>'Teilweise verarbeitet','unsupported'=>'Format nicht unterstützt','unavailable'=>'Provider nicht verfügbar','error'=>'Auslesefehler','limit'=>'Verarbeitungsgrenze erreicht']; ?>
<?php if ($data['media_areas']): ?>
<div class="page-heading"><div><p class="eyebrow">MEDIEN</p><h1>Deine Medienbereiche</h1><p class="lead">Geschützte Vorschauen und ausgewählte Bildinformationen.</p></div></div><section class="panel"><div class="group-list">
<?php foreach ($data['rows'] as $area): ?><article class="group-row"><h2><a href="<?= $e('/media?'.http_build_query(['space'=>$area['id']])) ?>"><?= $e($area['name']) ?></a></h2></article><?php endforeach ?>
<?php if ($data['rows']===[]): ?><p class="empty">Für dich sind keine Medienbereiche auf dieser Seite freigegeben.</p><?php endif ?></div><?php if ($data['next']!==null): ?><a href="<?= $e('/media?'.http_build_query(['after'=>$data['next']])) ?>">Weitere Bereiche</a><?php endif ?></section>
<?php else: ?>
<div class="page-heading"><div><p class="eyebrow">MEDIEN</p><h1><?= $e($data['folder']['name']??$data['space']['name']) ?></h1><p class="lead"><?= $e($data['space']['name']) ?> · bis zu 100 Einträge pro Seite</p></div><a href="/media">Alle Medienbereiche</a></div>
<p><a href="<?= $e('/media?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['parent']])) ?>">Ansicht aktualisieren</a><?php if ($data['folder']!==null): ?> · <a href="<?= $e('/media?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['folder']['parent_id']])) ?>">Übergeordneter Ordner</a><?php endif ?> · <a href="<?= $e('/files?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['parent']])) ?>">Zur Dateiablage</a></p>
<p>Vorschauen erscheinen nach der Verarbeitung durch den Worker. Mit „Ansicht aktualisieren“ kannst du den Stand erneut laden. Nicht unterstützte Dateien bleiben über ihre normalen Dateirechte nutzbar.</p>
<?php if ($data['media_caps']['process']): ?><p><a href="<?= $e('/media/rebuild?'.http_build_query(['space'=>$data['space']['id']])) ?>">Medienanalyse dieses Bereichs neu aufbauen</a></p><?php endif ?>
<div class="media-grid">
<?php foreach ($data['rows'] as $row): ?><article class="panel media-card">
<?php if ($row['kind']==='folder'): ?><div class="media-placeholder" aria-hidden="true">Ordner</div><h2><a href="<?= $e('/media?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$row['id']])) ?>"><?= $e($row['name']) ?></a></h2>
<?php else: ?><a class="media-thumb" href="<?= $e('/media/detail?'.http_build_query(['space'=>$data['space']['id'],'entry'=>$row['id']])) ?>"><?php if ($row['has_preview']): ?><img src="<?= $e('/media/preview?'.http_build_query(['space'=>$data['space']['id'],'entry'=>$row['id'],'revision'=>$row['revision']])) ?>" alt="<?= $e('Vorschau: '.$row['name']) ?>" loading="lazy" decoding="async"><?php else: ?><span class="media-placeholder"><?= $e($states[$row['media_status']]??'Nicht verfügbar') ?></span><?php endif ?></a><h2><a href="<?= $e('/media/detail?'.http_build_query(['space'=>$data['space']['id'],'entry'=>$row['id']])) ?>"><?= $e($row['name']) ?></a></h2><p class="subtle"><?= $e(number_format((int)$row['size_bytes'],0,',','.')) ?> Bytes · <?= $e($states[$row['media_status']]??'Nicht verfügbar') ?></p><?php endif ?></article><?php endforeach ?>
<?php if ($data['rows']===[]): ?><p class="empty">Dieser Ordner enthält noch keine Medien. Lade Dateien über die Dateiablage hoch.</p><?php endif ?></div>
<?php if ($data['next']!==null): ?><p><a href="<?= $e('/media?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['parent'],'after'=>$data['next']])) ?>">Weitere Einträge</a></p><?php endif ?>
<?php endif ?>

